import {getRacePack} from './race-registry.js';
const plain=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
export function validRaceRuntime(value){return value===undefined||plain(value)&&Object.keys(value).length===2&&typeof value.race==='string'&&typeof getRacePack(value.race)?.validRuntime==='function'&&getRacePack(value.race).validRuntime(value.state)===true;}
export function raceRuntimeContext(encounter,race){const pack=getRacePack(race);if(pack?.createRuntime&&!encounter.raceRuntime){const state=pack.createRuntime();if(!pack.validRuntime?.(state))throw Error('Invalid initial race runtime');encounter.raceRuntime={race,state};}const runtime=structuredClone(encounter.raceRuntime?.state??{});return {runtime,[race]:runtime,raceRuntime:{[race]:runtime},clock:encounter.treeCombatClock??0};}
export function commitRaceRuntime(encounter,race,patch){if(patch===undefined)return;const pack=getRacePack(race);raceRuntimeContext(encounter,race);const state={...encounter.raceRuntime.state,...structuredClone(patch)};if(!pack.validRuntime(state))throw Error('Invalid race runtime patch');encounter.raceRuntime.state=state;}
export function applyRaceRuntimeEffect(encounter,race,effect){if(!['raceResource','raceReactive'].includes(effect.type))return false;const pack=getRacePack(race);raceRuntimeContext(encounter,race);const old=structuredClone(encounter.raceRuntime.state);let next=effect.type==='raceReactive'?pack.applyReactiveEffect?.(old,effect,encounter.treeCombatClock??0):pack.applyRaceEffects?.(old,[effect]);if(next?.runtime)next=next.runtime;if(!pack.validRuntime(next))throw Error('Unsupported race runtime effect '+effect.type);encounter.raceRuntime.state=next;return true;}

export function equipmentSkillContext(s){const ids=new Set(Object.values(s.equip??{}));const equippedLegends=(s.inventory??[]).filter(i=>ids.has(i.id)&&i.exclusive).map(i=>({id:i.id,legendaryId:i.legendaryId,exclusiveId:i.exclusive.id,castCount:s.equipmentRuntime?.byId?.[i.id]?.castCount??0}));return {equippedLegends,exclusiveIds:[...new Set(equippedLegends.map(i=>i.exclusiveId))]};}
export function countEquippedSkillCast(s){s.equipmentRuntime??={version:1,byId:{}};for(const id of new Set(Object.values(s.equip??{}).filter(Boolean))){if(s.inventory?.some(i=>i.id===id&&i.legendaryId==='infinity-gauntlet'))continue;const r=s.equipmentRuntime.byId[id]??={combatMs:0,attackCount:0,castCount:0};r.castCount++;}}
